import{_ as u,a0 as r,w as i,s as p,ao as m,I as s,x as n,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const z=JSON.parse('{"title":"禁用Ubuntu 13.10的Amazon及远程内容获取 | LCTT x X-CMD","titleTemplate":false,"description":"禁用Ubuntu 13.10的Amazon及远程内容获取 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"禁用Ubuntu 13.10的Amazon及远程内容获取 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"禁用Ubuntu 13.10的Amazon及远程内容获取 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10","title":"禁用Ubuntu 13.10的Amazon及远程内容获取","tag":"201311","desc":""},"relativePath":"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10.md","filePath":"[post].md"}'),l={name:"201311/Disable Amazon & Remote Content Fetching In Ubuntu 13.10.md"};function b(d,t,T,f,g,C){const e=r("Link");return i(),p("div",null,[t[11]||(t[11]=m(`<h1 id="禁用ubuntu-13-10的amazon及远程内容获取" tabindex="-1">禁用Ubuntu 13.10的Amazon及远程内容获取 <a class="header-anchor" href="#禁用ubuntu-13-10的amazon及远程内容获取" aria-label="Permalink to “禁用Ubuntu 13.10的Amazon及远程内容获取”">​</a></h1><p>Ubuntu 13.10已经发布一段时间了，是时候坐下来配置一下系统来满足你的要求。Ubuntu 13.10配备了很多东西，当你安装或者升级时其实有些并不是你所需要的。</p><p>举个例子，当你安装或者升级到Ubuntu 13.10时，会自动启用Amazon和一些其他商业购物网站的功能。当你打开Unity Dash时这些Lens就会显示。当你在Dash处执行搜索时，类似Amazon的远程数据源中符合你搜索内容的选项也会发送过来。</p><p>这些由Canonical公司提供的新增特性可能对某些人有用，但是对另一些用户，这些特性可能是他们不需要的。</p><p>因为从远程数据源获取内容需要带宽，这就可能会对你的上网账单有负面影响，特别是当你住在一个根据流量计费的地域。</p><p>对于另一些对安全和隐私有担忧的用户来说，本地自动搜索远程源可能不是一个好主意。还有一些用户只是不想当他们在本地搜索时会有商业公司展示他们的产品。</p><p>这篇简单的教程就是教你当使用Ubuntu 13.10时如何快速禁用Amazon和所有远程内容获取。</p><p>在你的键盘上按组合键 <strong>Ctrl – Alt – T</strong> 显示终端。当它打开后运行下面的命令去禁用该功能。</p><pre><code>gsettings set com.canonical.Unity.Lenses remote-content-search &#39;none&#39;
</code></pre><p>如果你想要重新启用它，运行以下命令。</p><pre><code>gsettings set com.canonical.Unity.Lenses remote-content-search &#39;all&#39;
</code></pre><p>你需要重新登陆或者重启你的电脑使更改生效。在完成这些操作后，当你使用Ubuntu搜索时就没有远程源会被使用。</p><p>Enjoy!</p><hr>`,14)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.liberiangeek.net/2013/10/disable-amazon-remote-content-fetching-ubuntu-13-10/"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/10/disable-amazon-remote-content-fetching-ubuntu-13-10/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("译者：",-1)),o(e,{href:"https://github.com/whatever1992"},{default:a(()=>[...t[2]||(t[2]=[n("whatever1992",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const _=u(l,[["render",b]]);export{z as __pageData,_ as default};
